def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and out[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in comp); r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp); c1 = max(x for y, x in comp)
            # The frame has a one-cell gap in its top edge; fill its interior
            # with 2 and project a 2-colored ray leftward from that gap.
            top = {x for y, x in comp if y == r0}
            gaps = [x for x in range(c0, c1 + 1) if x not in top]
            if len(gaps) == 1 and c0 < gaps[0] < c1 and r1 > r0 + 1:
                gap = gaps[0]
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        if out[y][x] == 0:
                            out[y][x] = 2
                if r0 > 0:
                    for x in range(gap + 1):
                        if out[r0 - 1][x] == 0:
                            out[r0 - 1][x] = 2
    return out
